import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Package, Truck, CheckCircle, Clock } from 'lucide-react';
import './Dashboard.css';

const Dashboard = () => {
    const [bookings, setBookings] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchBookings = async () => {
            try {
                const res = await axios.get("http://localhost:9023/api/parcels/all");
                console.log("Check Backend Data:", res.data); // Inspect (F12) mein check karne ke liye
                setBookings(res.data);
            } catch (err) {
                console.error("Data fetch error:", err);
            } finally {
                setLoading(false);
            }
        };
        fetchBookings();
    }, []);

    return (
        <div className="dashboard-wrapper">
            <div className="dashboard-content">
                <header className="db-header">
                    <h2>Welcome back, <span className="gold-text">Aarti</span> 👋</h2>
                    <p>Manage your SafeParcel deliveries and overview</p>
                </header>

                <div className="stats-grid">
                    <div className="stat-card blue-border">
                        <div className="stat-icon bg-blue"><Package size={24} /></div>
                        <div className="stat-text">
                            <h3>{bookings.length}</h3>
                            <p>Total Bookings</p>
                        </div>
                    </div>
                    <div className="stat-card gold-border">
                        <div className="stat-icon bg-gold"><Truck size={24} /></div>
                        <div className="stat-text">
                            <h3>{bookings.filter(b => (b.status === 'IN_TRANSIT' || b.status === 'In Transit')).length}</h3>
                            <p>Active Shipments</p>
                        </div>
                    </div>
                    <div className="stat-card green-border">
                        <div className="stat-icon bg-green"><CheckCircle size={24} /></div>
                        <div className="stat-text">
                            <h3>{bookings.filter(b => (b.status === 'DELIVERED' || b.status === 'Delivered')).length}</h3>
                            <p>Completed</p>
                        </div>
                    </div>
                </div>

                <div className="table-section">
                    <div className="table-header">
                        <h3>Recent Transactions</h3>
                    </div>
                    <div className="table-container">
                        <table>
                            <thead>
                                <tr>
                                    <th>Id</th>
                                    <th>Tracking Id</th>
                                    <th>Customer</th>
                                    <th>From-To</th>
                                    <th>Vehicle</th>
                                    <th>Status</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr><td colSpan="7" className="text-center">Loading Data...</td></tr>
                                ) : bookings.length > 0 ? (
                                    bookings.slice(0, 10).map((order, index) => (
                                        <tr key={order.trackingId || index}>
                                            {/* 1. ID (Ya toh backend ki ID, ya loop index) */}
                                            <td>{order.id || index + 1}</td>

                                            {/* 2. Tracking ID */}
                                            <td><strong>{order.trackingId || "N/A"}</strong></td>

                                            {/* 3. Customer Name (Sare possible names handle kiye hain) */}
                                            <td>{order.userName || order.customerName || order.senderName || "Aastha"}</td>

                                            {/* 4. From-To (Source aur Destination addresses) */}
                                            <td>
                                                {(order.sourceAddress || order.fromLocation || "Karnal")} 
                                                {" → "} 
                                                {(order.destinationAddress || order.toLocation || "Radaur")}
                                            </td>

                                            {/* 5. Vehicle */}
                                            <td className="capitalize">{order.vehicleType || order.vehicle || "Bike"}</td>

                                            {/* 6. Status */}
                                            <td>
                                                <span className={`status-tag ${(order.status || 'delivered').toLowerCase()}`}>
                                                    {order.status || 'DELIVERED'}
                                                </span>
                                            </td>

                                            {/* 7. Action */}
                                            <td>
                                                <button className="manage-btn">Manage</button>
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr><td colSpan="7" className="text-center">No bookings found.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
